sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    if (!gs.nil(current.name)) {
        var gr = new GlideRecord('x_1882833_organi_0_shozoku');
        gr.addQuery('user_id', current.name);
        gr.addQuery('kenmu_number', 1);
        gr.query();

        if (gr.next()) {
            current.name_kanji = gr.user_id.u_ukanji_name;
            current.number = gr.user_id.u_number;
        }
        current.update();

